package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index)
 */
public class MultidimensionalCounter_getCounts_TriageGen1Test {

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_NegativeIndex_ThrowsException() {
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        counter.getCounts(-1);
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexEqualToSize_ThrowsException() {
        // Size = 2 * 3 = 6
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        counter.getCounts(6);
    }

    @Test
    public void testGetCounts_ZeroIndex() {
        // For a 2D counter (2, 3), the indices are mapped linearly.
        // Total size is 6.
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        int[] expected = {0, 0};
        assertArrayEquals(expected, counter.getCounts(0));
    }

    @Test
    public void testGetCounts_FirstDimensionBoundary() {
        // Counter (2, 3)
        // Dimensions: d0=2, d1=3. Total size = 6.
        // The logic uses uniCounterOffset and 'last' dimension logic.
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);

        // Index 0 -> [0, 0]
        // Index 1 -> [0, 1]
        // Index 2 -> [0, 2]
        // Index 3 -> [1, 0]
        // Index 4 -> [1, 1]
        // Index 5 -> [1, 2]

        assertArrayEquals(new int[]{0, 1}, counter.getCounts(1));
        assertArrayEquals(new int[]{0, 2}, counter.getCounts(2));
        assertArrayEquals(new int[]{1, 0}, counter.getCounts(3));
    }

    @Test
    public void testGetCounts_SingleDimension() {
        // Test with dimension = 1
        MultidimensionalCounter counter = new MultidimensionalCounter(5);
        // In a 1D counter, the first loop (for i < last) won't execute because last = 0
        // The second part (while count < index) will handle it.

        assertArrayEquals(new int[]{0}, counter.getCounts(0));
        assertArrayEquals(new int[]{1}, counter.getCounts(1));
        assertArrayEquals(new int[]{2}, counter.getCounts(2));
        assertArrayEquals(new int[]{4}, counter.getCounts(4));
    }

    @Test
    public void testGetCounts_HighDimension() {
        // Test with dimension = 3
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2);
        // Total size = 8

        assertArrayEquals(new int[]{0, 0, 0}, counter.getCounts(0));
        assertArrayEquals(new int[]{0, 0, 1}, counter.getCounts(1));
        assertArrayEquals(new int[]{0, 1, 0}, counter.getCounts(2));
        assertArrayEquals(new int[]{0, 1, 1}, counter.getCounts(3));
        assertArrayEquals(new int[]{1, 0, 0}, counter.getCounts(4));
        assertArrayEquals(new int[]{1, 1, 1}, counter.getCounts(7));
    }

    @Test
    public void testGetCounts_LargeIndex() {
        // Test to ensure the while loops and offsets handle larger ranges correctly
        MultidimensionalCounter counter = new MultidimensionalCounter(10, 10, 10);
        int[] result = counter.getCounts(999);
        assertArrayEquals(new int[]{9, 9, 9}, result);
    }
}
